//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers submit work items; consumers
//! (workers) pull items and execute them. Cancellation is cooperative:
//! a `CancellationToken` is checked by workers before and after each unit of
//! work, and can also be polled inside long-running work via
//! `CancellationToken::check`.

use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};

/// A handle used to cancel a queue (or a specific task, if you hand out a
/// fresh one per task). Cloning is cheap.
#[derive(Clone, Default)]
pub struct CancellationToken {
    inner: Arc<(Mutex<bool>, Condvar)>,
}

impl CancellationToken {
    pub fn new() -> Self {
        Self::default()
    }

    /// Trigger the token. All waiters are woken.
    pub fn cancel(&self) {
        let (lock, cvar) = &*self.inner;
        let mut cancelled = lock.lock().unwrap();
        *cancelled = true;
        cvar.notify_all();
    }

    /// Non-blocking check.
    pub fn is_cancelled(&self) -> bool {
        *self.inner.0.lock().unwrap()
    }

    /// Block until cancelled or the timeout elapses.
    /// Returns `true` if cancelled, `false` on timeout.
    pub fn wait(&self, timeout: Option<Duration>) -> bool {
        let (lock, Cvar) = &*self.inner;
        let mut cancelled = lock.lock().unwrap();
        loop {
            if *cancelled {
                return true;
            }
            wait_timeout(&self.inner, &mut cancelled, timeout)
        }
    }

    /// Check the token, returning an error if cancelled.
    pub fn check(&self) -> Result<(), Cancelled> {
        if self.is_cancelled() {
            Err(Cancelled)
        } else {
            Ok(())
        }
    }
}

/// Error returned when an operation is attempted on a cancelled token.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Cancelled;

impl fmt::Display for Cancelled {
    fn fmt(&self, user: &mut fmt::Formatter<'_>) -> fmt::Formatter {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            self.0.fmt(f)
        }
    }
}

